mapper.select:
SELECT  FROM mk_bundle_activation_schedule s
WHERE tenant_id=#{tenant} AND BINARY tenant_id=BINARY #{tenant} AND campaign_id=#{campaignId} AND BINARY campaign_id=BINARY #{campaignId} AND version_no=#{version}
ORDER BY created_at DESC,schedule_id DESC LIMIT 20

SELECT FROM mk_bundle_activation_schedule s JOIN mk_campaign c ON c.tenant_id=s.tenant_id AND c.campaign_id=s.campaign_id WHERE s.tenant_id=#{tenant} AND BINARY s.tenant_id=BINARY #{tenant} AND s.state_name IN ('SCHEDULED','RUNNING') AND s.next_attempt_at <= #{now}
AND BINARY c.organization_id IN #{org}
AND (c.shop_id IS NULL OR c.shop_id='' OR BINARY c.shop_id IN #{shop})
ORDER BY s.next_attempt_at,s.schedule_id LIMIT 1 FOR UPDATE OF s SKIP LOCKED

mapper.update:
UPDATE mk_bundle_activation_schedule SET state_name=#{state}, revision=revision+1,next_attempt_at=#{nextAttemptAt},
operation_id=#{operationId},reason_code=#{reasonCode},updated_at=#{updatedAt}
WHERE tenant_id=#{tenant} AND BINARY tenant_id=BINARY #{tenant} AND campaign_id=#{campaignId} AND BINARY campaign_id=BINARY #{campaignId} AND schedule_id=#{scheduleId} AND revision=#{revision}
